let button = document.querySelector("#myBtn");

button.addEventListener("click", () => {
  console.log("Button was clicked!");
});

// Multiple listeners on the same element
button.addEventListener("click", () => {
  document.body.classList.toggle("highlight");
});

let button = document.querySelector("#myBtn");

function handleClick() {
  console.log("Clicked!");
  button.removeEventListener("click", handleClick);
}

button.addEventListener("click", handleClick);
// First click logs "Clicked!", then removes itself.

let box = document.querySelector(".box");

// Mouse events
box.addEventListener("click", () => console.log("clicked"));
box.addEventListener("mouseover", () => {
  box.style.backgroundColor = "lightblue";
});
box.addEventListener("mouseout", () => {
  box.style.backgroundColor = "white";
});

// Keyboard event
document.addEventListener("keydown", (e) => {
  console.log("Key: " + e.key);
  if (e.key === "Escape") console.log("Escape pressed!");
});

let form = document.querySelector("#myForm");

form.addEventListener("submit", (e) => {
  e.preventDefault();  // stop page reload
  let name = form.querySelector("#name").value;
  console.log("Name: " + name);
});

// Real-time input tracking
let input = document.querySelector("#search");
input.addEventListener("input", (e) => {
  console.log("Current value: " + e.target.value);
});

// event.target tells you WHAT was clicked
document.querySelector(".list").addEventListener("click", (e) => {
  if (e.target.tagName === "LI") {
    console.log("Clicked item: " + e.target.textContent);
  }
});

// Keyboard shortcuts
document.addEventListener("keydown", (e) => {
  if (e.ctrlKey && e.key === "s") {
    e.preventDefault();
    console.log("Save shortcut!");
  }
});

// Stop form reload
let form = document.querySelector("form");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  console.log("Form submitted without page reload!");
});

// Stop link navigation
let link = document.querySelector("a.no-nav");
link.addEventListener("click", (e) => {
  e.preventDefault();
  console.log("Navigation blocked: " + link.href);
});

// Prevent context menu
document.addEventListener("contextmenu", (e) => {
  e.preventDefault();
  console.log("Right-click menu blocked");
});
